-- 0045_cn35_seed_test001_account.sql
-- 内置测试账号 test001（密码 test001，等级 100，钻石 2000，拥有当前全部 1,251 名准入同伴与 235 只准入魔宠）。
-- 所有语句均幂等，兼容新库（如单 APK 首次启动）与已有 test001 的存档库。

INSERT INTO cn35_accounts (
    he_account_id, user_id, token, sk, user_name, account_name, password_hash,
    sdk_account_id, device_id, is_new_user, tutorial_finish, last_server_id,
    created_at, updated_at
)
SELECT
    'he0714398b15989906',
    '681abf0d7485',
    '2a0ff130bc72341546de613f87d04ba8',
    '689811402a83c39bc75304287495763a',
    'test001',
    'test001',
    'e477e57d59faf9ee8cc458a1c43f9fe847c61d0de25837a940d7c60de2546044',
    '',
    '',
    0,
    1,
    '1',
    '2026-11-01T00:00:00Z',
    '2026-11-01T00:00:00Z'
WHERE NOT EXISTS (
    SELECT 1 FROM cn35_accounts
    WHERE account_name = 'test001'
       OR user_id = '681abf0d7485'
       OR he_account_id = 'he0714398b15989906'
);

UPDATE cn35_accounts
SET user_name = CASE WHEN user_name = '' THEN 'test001' ELSE user_name END,
    account_name = 'test001',
    password_hash = 'e477e57d59faf9ee8cc458a1c43f9fe847c61d0de25837a940d7c60de2546044',
    is_new_user = 0,
    tutorial_finish = 1,
    last_server_id = CASE WHEN last_server_id = '' THEN '1' ELSE last_server_id END,
    updated_at = '2026-11-01T00:00:00Z'
WHERE account_name = 'test001' OR user_id = '681abf0d7485';

INSERT INTO cn35_player_profiles (
    user_id, level, exp, max_exp, ap, max_ap, ap_updated_at,
    bp, max_bp, leader_unit_id, login_bonus_receivable_sec,
    guild_name_snapshot, helper_unit_id, created_at, updated_at
)
SELECT
    u.user_id, 100, 0, 27690, 119, 119, '2026-11-01T00:00:00Z',
    300, 300, '348', 0,
    '', '', '2026-11-01T00:00:00Z', '2026-11-01T00:00:00Z'
FROM cn35_accounts u
WHERE u.account_name = 'test001'
ON CONFLICT(user_id) DO UPDATE SET
    level = 100,
    exp = 0,
    max_exp = 27690,
    ap = 119,
    max_ap = 119,
    bp = 300,
    max_bp = 300,
    updated_at = '2026-11-01T00:00:00Z';

INSERT INTO cn35_player_balances (user_id, currency, amount, updated_at)
SELECT u.user_id, 'coin', 2000, '2026-11-01T00:00:00Z'
FROM cn35_accounts u
WHERE u.account_name = 'test001'
ON CONFLICT(user_id, currency) DO UPDATE SET
    amount = 2000,
    updated_at = '2026-11-01T00:00:00Z';

INSERT INTO cn35_player_balances (user_id, currency, amount, updated_at)
SELECT u.user_id, 'gacha_point', 1000000, '2026-11-01T00:00:00Z'
FROM cn35_accounts u
WHERE u.account_name = 'test001'
ON CONFLICT(user_id, currency) DO UPDATE SET
    amount = MAX(cn35_player_balances.amount, 1000000),
    updated_at = '2026-11-01T00:00:00Z';

INSERT INTO cn35_player_balances (user_id, currency, amount, updated_at)
SELECT u.user_id, 'medal', 5000, '2026-11-01T00:00:00Z'
FROM cn35_accounts u
WHERE u.account_name = 'test001'
ON CONFLICT(user_id, currency) DO UPDATE SET
    amount = MAX(cn35_player_balances.amount, 5000),
    updated_at = '2026-11-01T00:00:00Z';

