    u.user_id, s.uuid, s.monster_id, NULL, 1, 0,
    '1.000', '1.000', NULL, NULL, '2026-11-01T00:00:00Z', '2026-11-01T00:00:00Z'
FROM cn35_accounts u
CROSS JOIN seed_monsters s
