INSERT OR IGNORE INTO cn35_inventory_grants (user_id, grant_key, unit_id, created_at)
SELECT
    u.user_id, 'cn350-test001-builtin-v1-monster', s.monster_id, '2026-11-01T00:00:00Z'
FROM cn35_accounts u
CROSS JOIN seed_monsters s
WHERE u.account_name = 'test001';

INSERT OR IGNORE INTO cn35_inventory_grants (user_id, grant_key, unit_id, created_at)
SELECT
    u.user_id, 'cn350-min350-04-stage-base-v1-monster', 39, '2026-11-01T00:00:00Z'
FROM cn35_accounts u
WHERE u.account_name = 'test001';

INSERT OR IGNORE INTO cn35_player_decks (user_id, party_id, display_order, created_at, updated_at)
SELECT u.user_id, '1', 0, '2026-11-01T00:00:00Z', '2026-11-01T00:00:00Z'
FROM cn35_accounts u
WHERE u.account_name = 'test001'
  AND NOT EXISTS (SELECT 1 FROM cn35_player_decks d WHERE d.user_id = u.user_id);

WITH default_slots(slot_index, unit_id) AS (
    VALUES (0, 348), (1, 336), (2, 156), (3, 296), (4, 375)
)
INSERT OR IGNORE INTO cn35_player_deck_slots (user_id, party_id, slot_index, unit_id)
SELECT u.user_id, '1', s.slot_index, s.unit_id
FROM cn35_accounts u
CROSS JOIN default_slots s
WHERE u.account_name = 'test001'
  AND EXISTS (SELECT 1 FROM cn35_player_decks d WHERE d.user_id = u.user_id AND d.party_id = '1')
  AND NOT EXISTS (SELECT 1 FROM cn35_player_deck_slots ds WHERE ds.user_id = u.user_id AND ds.party_id = '1');
